    private void modelSettings(){var root=document().node(document().root());var properties=root.properties();ComboBox<String> copula=new ComboBox<>();copula.getItems().setAll("LEGACY_SELECTED_EQUATION","ADJUSTED_2025");copula.setValue(DiagramModels.string(properties,"copulaEstimator","LEGACY_SELECTED_EQUATION"));copula.setDisable(document().family()==Family.CBSEM);CheckBox means=new CheckBox("Estimate a mean/intercept structure (CB-SEM)");means.setSelected(DiagramModels.bool(properties,"meanStructure",false));means.setDisable(document().family()!=Family.CBSEM);ComboBox<String> source=nodeChoice(),target=nodeChoice();source.setValue(DiagramModels.string(properties,"focalSource",source.getValue()));target.setValue(DiagramModels.string(properties,"focalTarget",target.getValue()));TextArea advanced=new TextArea(new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(properties));advanced.setPrefRowCount(12);optional("Model settings",new VBox(8,means,UiAppearance.label("Copula workflow (adjusted enables all marked equations and polynomial combinations)"),copula,UiAppearance.label("PROCESS focal source / outcome"),source,target,UiAppearance.label("Advanced model options"),advanced),()->{TypedDiagram.boundedJson(advanced.getText(),65536,32);var options=JsonParser.parseString(advanced.getText()).getAsJsonObject();if(document().family()!=Family.CBSEM)options.addProperty("copulaEstimator",copula.getValue());if(document().family()==Family.CBSEM)options.addProperty("meanStructure",means.isSelected());if(document().family()==Family.PROCESS){options.addProperty("focalSource",source.getValue());options.addProperty("focalTarget",target.getValue());}record(document().with(new org.brightstats.model.TypedDiagram.Node(root.id(),root.type(),root.label(),root.x(),root.y(),options)));});}
    private void properties(String id){if(document().nodes().stream().anyMatch(node->node.id().equals(id))){var node=document().node(id);if(node.type()==ElementType.ROOT){modelSettings();return;}TextField label=new TextField(node.label()),x=new TextField(Double.toString(node.x())),y=new TextField(Double.toString(node.y()));ComboBox<String> column=new ComboBox<>();column.getItems().setAll(columns);column.setValue(DiagramModels.string(node.properties(),"column",columns.isEmpty()?null:columns.getFirst()));TextArea advanced=new TextArea(new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(node.properties()));advanced.setPrefRowCount(12);VBox body=new VBox(8,UiAppearance.label("Display name"),label,new Label(node.type()==ElementType.DONGLE?"Anchor offset X / Y":"Position X / Y"),x,y);if(node.type().observed())body.getChildren().addAll(UiAppearance.label("Data column (independent of display name)"),column);body.getChildren().addAll(UiAppearance.label("Statistical / appearance properties (JSON)"),advanced);optional(friendly(node.type())+" properties",body,()->{TypedDiagram.boundedJson(advanced.getText(),65536,32);JsonObject props=JsonParser.parseString(advanced.getText()).getAsJsonObject();if(node.type().observed())props.addProperty("column",column.getValue());record(document().with(new org.brightstats.model.TypedDiagram.Node(id,node.type(),label.getText(),Double.parseDouble(x.getText().trim()),Double.parseDouble(y.getText().trim()),props)));});}else if(document().links().stream().anyMatch(link->link.id().equals(id))){var link=document().link(id);TextArea properties=new TextArea(new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(link.properties()));properties.setPrefRowCount(15);Label help=new Label(document().family()==Family.CBSEM?"Parameter fields: free (boolean), value, equality (shared parameter name), lower, upper, scale. Missing fields retain automatic defaults. Text labels are separate annotations.":document().family()==Family.GSCA&&link.type().measurement()?"Measurement masks: weight, loading (booleans), initialWeight. Components need at least one weighted indicator.":"Structural coefficients are estimated. Geometry/appearance properties do not fix a coefficient. Add a separate connection label for text.");help.setWrapText(true);optional("Connection properties",new VBox(8,help,properties),()->{TypedDiagram.boundedJson(properties.getText(),65536,32);record(document().with(new Link(id,link.type(),link.source(),link.target(),JsonParser.parseString(properties.getText()).getAsJsonObject())));});}else{var note=document().annotations().stream().filter(value->value.id().equals(id)).findFirst().orElseThrow();TextArea text=new TextArea(note.text());TextField x=new TextField(Double.toString(note.x())),y=new TextField(Double.toString(note.y())),width=new TextField(Double.toString(note.width())),height=new TextField(Double.toString(note.height()));optional("Note / label",new VBox(8,text,UiAppearance.label("Position / attachment offset X and Y"),x,y,UiAppearance.label("Width and height"),width,height),()->record(document().with(new Annotation(id,note.type(),note.attachment(),text.getText(),Double.parseDouble(x.getText()),Double.parseDouble(y.getText()),Double.parseDouble(width.getText()),Double.parseDouble(height.getText())))));}}
    private void optional(String title,VBox content,Runnable apply){Dialog<ButtonType> popup=new Dialog<>();popup.initOwner(dialog.getDialogPane().getScene()==null?owner:dialog.getDialogPane().getScene().getWindow());popup.setTitle(title);content.setPadding(new Insets(12));content.setPrefWidth(640);Label error=new Label();error.setWrapText(true);content.getChildren().add(error);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(Math.min(650,Math.max(300,content.getChildren().size()*42)));popup.getDialogPane().setContent(scroll);popup.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);popup.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{apply.run();}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});popup.showAndWait();}
    private void export(){FileChooser chooser=new FileChooser();chooser.setTitle("New typed model PNG or SVG file");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Diagram graphics","*.png","*.svg"));var file=chooser.showSaveDialog(dialog.getDialogPane().getScene().getWindow());if(file==null)return;guard(()->{try{String name=file.getName().toLowerCase(Locale.ROOT);view.applyCss();view.layout();if(name.endsWith(".svg"))Files.writeString(file.toPath(),TypedDiagramSvg.render(document(),document().family()+" model"),java.nio.charset.StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);else if(name.endsWith(".png"))GraphicExport.png(file.toPath(),view,1);else throw new IllegalArgumentException("Choose .png or .svg.");status.setText("Saved diagram graphic.");}catch(Exception problem){throw new IllegalArgumentException(problem.getMessage(),problem);}});}
    private static javafx.util.StringConverter<ElementType> converter(){return new javafx.util.StringConverter<>(){public String toString(ElementType type){return type==null?"":friendly(type);}public ElementType fromString(String text){return ElementType.valueOf(text);}};}
    private static String friendly(ElementType type){return switch(type){case LATENT_VARIABLE->"PLS construct";case GSCA_LATENT_VARIABLE->"GSCA component";case PROCESS_MODEL_LATENT_VARIABLE->"PROCESS composite";case PROCESS_MODEL_CONTROL_VARIABLE->"Control composite";case CBSEM_LATENT_VARIABLE->"Latent variable";case CBSEM_ERROR_TERM->"Error term";case STANDARD_MANIFEST_VARIABLE,GSCA_STANDARD_MANIFEST_VARIABLE,PROCESS_MODEL_STANDARD_MANIFEST_VARIABLE,CBSEM_STANDARD_MANIFEST_VARIABLE->"Observed indicator";case REGRESSION_INDEPENDENT_VARIABLE->"Predictor";case REGRESSION_DEPENDENT_VARIABLE->"Outcome";case REGRESSION_INTERCEPT->"Intercept";case GAUSSIAN_COPULA->"Gaussian copula marker";case QUADRATIC_EFFECT,PROCESS_MODEL_QUADRATIC_EFFECT->"Quadratic effect";case POSTIT->"Note";case NODE_EXTERNAL_LABEL->"External node label";case CONNECTION_LABEL->"Connection label";case DONGLE->"Path attachment anchor";default->type.name();};}
    static Optional<Result> show(Window owner,Document document,List<String> columns,double[][] data){return new TypedModelEditor(owner,document,columns,data).dialog.showAndWait();}
    static Document smoke(Window owner,Document document,List<String> columns,double[][] data,Path output)throws Exception{return smoke(owner,document,columns,data,output,"typed-"+document.family().name().toLowerCase(Locale.ROOT));}
    static Document smoke(Window owner,Document document,List<String> columns,double[][] data,Path output,String prefix)throws Exception{var editor=new TypedModelEditor(owner,document,columns,data);editor.dialog.show();if(!editor.validate())throw new AssertionError("Typed editor initial input rejected: "+editor.validation.getText());String id=document.nodes().stream().filter(node->node.type()!=ElementType.ROOT).findFirst().orElseThrow().id();editor.record(document.move(Set.of(id),30,15));editor.show(editor.history.undo(),Set.of(id));if(!editor.document().equals(document))throw new AssertionError("Typed editor undo changed document");editor.show(editor.history.redo(),Set.of(id));editor.record(editor.document().with(new Annotation("smoke_note",ElementType.POSTIT,"","Synthetic note <&> α",80,DiagramGeometry.bounds(editor.document()).height()+40,240,90)));editor.view.applyCss();editor.view.layout();Files.writeString(output.resolve(prefix+".svg"),TypedDiagramSvg.render(editor.document(),"Typed "+document.family()));Files.deleteIfExists(output.resolve(prefix+".png"));GraphicExport.png(output.resolve(prefix+".png"),editor.view,1);Document result=editor.document();editor.dialog.setResult(new Result(result,false,false));editor.dialog.close();return result;}
